-- ═══════════════════════════════════════════════════════════════════════════════
-- Controle de Custos — Fontes Pagadoras (preço negociado por convênio/exame)
-- Migration: 20260904110000_custo_fontes_pagadoras.sql
--
-- A aba "Fontes Pagadoras" vivia inteiramente em memória (SEED_PAYORS em
-- src/hooks/useCostControl.ts) e era rotulada como mock. Esta migration cria
-- a tabela que passa a sustentar aquela tela e semeia preços reais extraídos
-- do banco MySQL do APLIS (ver .scratch/controle-custos-fontes-pagadoras-busca),
-- restritos aos TUSS já cadastrados em public.custo_exames.
--
-- Mapeamento das colunas de origem (MySQL):
--   fatinstituicao.NomFantasia (WHERE FontePagadora = 1)  → fonte_pagadora
--     'FontePagadora' é a flag real do schema APLIS que identifica a
--     instituição que efetivamente paga a conta — não a instituição
--     referenciadora (clínica que envia a amostra), nem o "Local" (unidade).
--   fatconvenio.NomConvenio                                → tabela_associada
--     o plano/acordo negociado especificamente sob aquela fonte pagadora
--     (uma fonte pode administrar várias — ex.: AMHP-DF tem 37 convênios
--     distintos vinculados, cada um com sua própria negociação de preço).
--   fattabelaprocedimento.Codigo                           → tuss
--   COALESCE(fatconvenioprocedimento.Valor, fattabelaprocedimento.Valor) → valor
--     o valor negociado (fatconvenioprocedimento) tem prioridade sobre o
--     valor-base da tabela de preço; a maioria das linhas só tem o negociado.
--
-- Filtros aplicados na extração:
--   - fatinstituicao/fatconvenio/fatconvenioinstituicao/fattabelapreco/
--     fattabelaprocedimento todos com Inativo = 0
--   - fatconvenioinstituicao.DtaVigenciaIni/DtaVigenciaFim: só o contrato
--     vigente na data da extração (cada convênio acumula um histórico de
--     versões de preço; pegar todas gerava conflito de valor pro mesmo
--     TUSS — só a vigência atual é semeada)
--   - excluídos os convênios 'PARTICULAR' e 'CORTESIA': não são fonte
--     pagadora com tabela fixa, são categorias de preço negociado
--     caso-a-caso (a tela já tem 'Saldo de Caixa'/Particular tratado à
--     parte no mock, sem pretensão de refletir uma tabela real)
--   - Onde ainda restou mais de um valor vigente pro mesmo
--     (fonte, convênio, TUSS) — sobretudo códigos de peça cirúrgica com
--     preço por peça/fragmento (ex.: 40601226, 40601269) — foi semeado o
--     menor valor, coerente com a ordenação "mais barato primeiro" que a
--     própria tela já usa.
--
-- Mesmo padrão de public.custo_exames (20260903130000): CRUD simples sob
-- RLS, sem RPC, reaproveitando canViewBilling/canManageBilling.
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF to_regprocedure('public.current_user_has_permission(text)') IS NULL THEN
    RAISE EXCEPTION 'Função public.current_user_has_permission(text) não existe. Aplique 20260618010000_ensure_admin_update_policy.sql antes desta migration.';
  END IF;
END $$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1. TABELA
-- ═══════════════════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.custo_fontes_pagadoras (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  fonte_pagadora    TEXT NOT NULL CHECK (btrim(fonte_pagadora) <> ''),
  tabela_associada  TEXT NOT NULL DEFAULT '',
  tuss              TEXT NOT NULL DEFAULT '',
  valor             NUMERIC(12,2) NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE public.custo_fontes_pagadoras IS 'Preço negociado por fonte pagadora/convênio/TUSS, usado pela aba "Fontes Pagadoras" de Controle de Custos. tuss casa com custo_exames.tuss.';
COMMENT ON COLUMN public.custo_fontes_pagadoras.fonte_pagadora IS 'Instituição pagadora (fatinstituicao.NomFantasia WHERE FontePagadora = 1 no APLIS).';
COMMENT ON COLUMN public.custo_fontes_pagadoras.tabela_associada IS 'Convênio/plano negociado sob aquela fonte pagadora (fatconvenio.NomConvenio no APLIS) — uma mesma fonte pode ter vários.';

CREATE INDEX IF NOT EXISTS idx_custo_fontes_pagadoras_tuss ON public.custo_fontes_pagadoras (tuss);

CREATE OR REPLACE FUNCTION public.custo_fontes_pagadoras_set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_custo_fontes_pagadoras_updated_at ON public.custo_fontes_pagadoras;
CREATE TRIGGER trigger_custo_fontes_pagadoras_updated_at
  BEFORE UPDATE ON public.custo_fontes_pagadoras
  FOR EACH ROW EXECUTE FUNCTION public.custo_fontes_pagadoras_set_updated_at();

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2. RLS — mesmo gate da rota /cost-control (App.tsx: permission="canViewBilling")
-- ═══════════════════════════════════════════════════════════════════════════════

ALTER TABLE public.custo_fontes_pagadoras ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS custo_fontes_pagadoras_select_billing ON public.custo_fontes_pagadoras;
CREATE POLICY custo_fontes_pagadoras_select_billing ON public.custo_fontes_pagadoras
  FOR SELECT TO authenticated
  USING (public.current_user_has_permission('canViewBilling')
      OR public.current_user_has_permission('canManageBilling'));

DROP POLICY IF EXISTS custo_fontes_pagadoras_write_billing ON public.custo_fontes_pagadoras;
CREATE POLICY custo_fontes_pagadoras_write_billing ON public.custo_fontes_pagadoras
  FOR ALL TO authenticated
  USING (public.current_user_has_permission('canManageBilling'))
  WITH CHECK (public.current_user_has_permission('canManageBilling'));

